<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { nativeExamItems, nativePracticeItems } from '../../data/workspace'
import type { AssessmentMode, NativeExamItem, WorkspaceScore } from '../../data/workspace'
import { workflows } from '../../data/catalog'
import { useWorkspace } from '../../state/workspace'
import { useSimulator } from '../../state/simulator'
import { formatDate, formatDuration, matches } from './lib/domain'
import WorkspaceFrame from './WorkspaceFrame.vue'
import ActiveAssessmentBanner from './ActiveAssessmentBanner.vue'
import TheorySetup from './TheorySetup.vue'
import TheoryAnswerPane from './TheoryAnswerPane.vue'
import OperationSessionPanel from './OperationSessionPanel.vue'
import LearnerScoreHistory from './LearnerScoreHistory.vue'
import ScoreDetailModal from './ScoreDetailModal.vue'
import BaseModal from '../common/BaseModal.vue'
import UiIcon from '../common/UiIcon.vue'

const workspace = useWorkspace(), simulator = useSimulator()
const student = workspace.offlineStudent
const route = computed(() => workspace.data.examTab)
const query = ref(''), category = ref('')
const identityNo = ref(student.value?.studentNo || ''), identityName = ref(student.value?.name || ''), identityError = ref('')
const operationMinutes = ref(20), agreed = ref(false), resultFilter = ref<'wrong' | 'all' | 'passed'>('wrong'), showDetail = ref(false), leaving = ref(false)
const theory = computed(() => workspace.data.activeTheory?.returnPage === 'exam' && workspace.data.activeTheory.studentId === student.value?.id ? workspace.data.activeTheory : null)
const operation = computed(() => workspace.data.activeOperation?.returnPage === 'exam' && workspace.data.activeOperation.studentId === student.value?.id ? workspace.data.activeOperation : null)
const pending = computed(() => workspace.data.pendingLaunch?.returnPage === 'exam' && workspace.data.pendingLaunch.studentId === student.value?.id ? workspace.data.pendingLaunch : null)
const busy = computed(() => !!(workspace.data.activeTheory || workspace.data.activeOperation || workspace.data.pendingLaunch || workspace.data.recording.active))
const panelIsActive = computed(() => route.value === 'answer' && !!theory.value || route.value === 'operation' && !!(operation.value || pending.value))
const theorySelection = computed(() => {
  const match = route.value.match(/^(practice|exam):(T11|T12|wrong|favourites)$/)
  return match ? { mode: match[1] as AssessmentMode, bank: match[2] === 'T11' || match[2] === 'T12' ? match[2] : '', source: match[2] === 'wrong' ? 'wrong' as const : match[2] === 'favourites' ? 'favourites' as const : 'bank' as const } : null
})
const attention = computed(() => {
  const match = route.value.match(/^attention:(practice|exam):(practice|exam):(\d+)$/)
  const item = match ? (match[2] === 'practice' ? nativePracticeItems : nativeExamItems).find(item => item.id === Number(match[3])) : undefined
  return match && item ? { mode: match[1] as AssessmentMode, origin: match[2] as 'practice' | 'exam', item } : null
})
function unconfigured(item: NativeExamItem) { return item.note.includes('未提供独立完整评分定义') }
function operationAvailable(item: NativeExamItem) { return !!workspace.operationItems.value.find(operation => operation.id === item.flowId) && !!workflows.find(flow => flow.id === item.flowId) }
const attentionFlow = computed(() => workflows.find(flow => flow.id === attention.value?.item.flowId))
const nativeAssessment = computed(() => attentionFlow.value?.assessment)
function nativeRuleScope(item: NativeExamItem) {
  const flow = workflows.find(flow => flow.id === item.flowId)
  return flow?.assessment ? `原 Playbook ${flow.assessment.stages.length} 个阶段` : `工况派生训练 · ${flow?.steps.length || 0} 个步骤（非原阶段定义）`
}
const attentionBlocked = computed(() => !attention.value || !operationAvailable(attention.value.item) || attention.value.mode === 'exam' && unconfigured(attention.value.item))
const minutesError = computed(() => !Number.isInteger(operationMinutes.value) || operationMinutes.value < 1 || operationMinutes.value > 1440)
const examRows = computed(() => nativeExamItems.filter(item => (!category.value || item.type === category.value) && matches(`${item.id} ${item.name} ${item.type}`, query.value)))
const practiceRows = computed(() => nativePracticeItems.filter(item => (!category.value || item.type === category.value) && matches(`${item.id} ${item.name} ${item.type}`, query.value)))
const categories = computed(() => [...new Set((route.value === 'practice-index' ? nativePracticeItems : nativeExamItems).map(item => item.type))])
const myScores = computed(() => workspace.data.scores.filter(score => score.studentId === student.value?.id))
const lastScore = computed(() => myScores.value.find(score => score.id === workspace.data.lastScoreId))
const visibleResult = computed(() => lastScore.value?.scoreVisible === true)
const resultQuestions = computed(() => visibleResult.value ? lastScore.value?.details.filter(detail => detail.kind === 'question') || [] : [])
const resultDetails = computed(() => visibleResult.value ? lastScore.value?.details.filter(detail => resultFilter.value === 'wrong' ? !detail.passed : resultFilter.value === 'passed' ? detail.passed : true) || [] : [])
const correctCount = computed(() => resultQuestions.value.filter(detail => detail.passed).length)
const unansweredCount = computed(() => resultQuestions.value.filter(detail => detail.response === '未作答').length)
const wrongQuestions = computed(() => {
  if (!visibleResult.value) return []
  const hiddenIds = new Set(myScores.value.filter(score => !score.scoreVisible).flatMap(score => score.details.filter(detail => detail.kind === 'question').map(detail => detail.question?.id || detail.id)))
  return resultQuestions.value.flatMap(detail => !detail.passed && detail.question && !hiddenIds.has(detail.question.id) ? [detail.question] : [])
})
const defaultTheoryCount = computed(() => theorySelection.value?.mode === 'practice' && theorySelection.value.bank ? workspace.data.questions.filter(question => question.tags.includes(theorySelection.value!.bank)).length : 100)
const theoryItemNote = computed(() => theorySelection.value?.mode === 'exam' && theorySelection.value.bank ? nativeExamItems.find(item => item.type.startsWith(theorySelection.value!.bank))?.note || '' : '')
function go(next: string) { workspace.data.examTab = next; workspace.persist() }
function chooseTheory(bank: string, mode: AssessmentMode) { go(`${mode}:${bank}`) }
function selectItem(item: NativeExamItem, mode: AssessmentMode, origin: 'practice' | 'exam') {
  if (!item.flowId) chooseTheory(item.id === 1 ? 'T11' : 'T12', mode)
  else go(`attention:${mode}:${origin}:${item.id}`)
}
function login() {
  if (busy.value) return
  identityError.value = !identityNo.value.trim() || !identityName.value.trim() ? '请输入学号和姓名。这是本地身份录入，不使用密码或服务器认证。' : ''
  if (identityError.value) return
  if (workspace.setOfflineIdentity(identityNo.value, identityName.value)) { identityError.value = ''; go('exam-index') }
  else identityError.value = '本地身份未保存。请检查学号是否已被其他姓名使用，并查看系统提示。'
}
function startOperation() {
  const selection = attention.value
  if (!selection || attentionBlocked.value || minutesError.value || !agreed.value || busy.value) return
  const associationOnly = unconfigured(selection.item)
  const title = associationOnly ? `关联流程练习 · ${selection.item.name}（未配置独立评分定义）` : `${selection.item.name} · 单机${selection.mode === 'exam' ? '考评' : '练习'}`
  const started = workspace.requestOperation({ operationId: selection.item.flowId, title, mode: selection.mode, returnPage: 'exam', durationMinutes: operationMinutes.value })
  if (started || workspace.data.pendingLaunch?.returnPage === 'exam' && workspace.data.pendingLaunch.operationId === selection.item.flowId) go('operation')
}
function retryWrong() {
  if (!lastScore.value || !wrongQuestions.value.length || busy.value) return
  workspace.startTheory({ questions: wrongQuestions.value, title: `错题复习 · ${lastScore.value.title}`, mode: 'practice', returnPage: 'exam', maxScore: 100 })
}
function exportResult(score: WorkspaceScore) { if (score.scoreVisible) workspace.exportScores([score], `单机结果-${workspace.safeName(score.title)}.csv`) }
function leave() {
  if (theory.value || operation.value || pending.value) leaving.value = true
  else simulator.navigate('overview')
}
function leaveKeepingSession() { workspace.persist(); leaving.value = false; simulator.navigate('overview') }
function endAndLeave() {
  if (theory.value?.deadlineAt != null && Date.now() >= theory.value.deadlineAt) workspace.submitTheory('timeout')
  else if (operation.value?.deadlineAt != null && Date.now() >= operation.value.deadlineAt) workspace.submitOperation('timeout')
  else workspace.cancelAssessment()
  leaving.value = false
  go('menu')
  simulator.navigate('overview')
}
function validRoute(value: string) { return ['menu', 'practice-menu', 'exam-login', 'exam-index', 'practice-index', 'answer', 'operation', 'result', 'history'].includes(value) || /^(practice|exam):(T11|T12|wrong|favourites)$/.test(value) || /^attention:(practice|exam):(practice|exam):\d+$/.test(value) }
if (!validRoute(route.value)) go(theory.value ? 'answer' : operation.value || pending.value ? 'operation' : 'menu')
watch(route, (next, previous) => {
  if (next !== previous) { query.value = ''; category.value = ''; showDetail.value = false }
  if (next === 'exam-login') { identityNo.value = student.value?.studentNo || ''; identityName.value = student.value?.name || ''; identityError.value = '' }
  if (attention.value) { operationMinutes.value = attention.value.item.minutes; agreed.value = false }
}, { immediate: true })
watch(() => lastScore.value?.id, () => { resultFilter.value = 'wrong'; showDetail.value = false })
watch(() => [theory.value?.id, operation.value?.id, pending.value?.id], () => { if (!theory.value && !operation.value && !pending.value) leaving.value = false })
</script>

<template>
  <WorkspaceFrame title="单机练习 / 考评系统" subtitle="理论练习、操作训练与本地考评" icon="ClipboardCheck" data-testid="exam-workspace">
    <template #navigation><div class="toolbar identity-bar"><span class="ws-subtext" data-testid="exam-current-identity">本地身份：{{ student?.name }} · {{ student?.studentNo }}</span><span class="badge badge-muted">身份只用于本浏览器记录署名</span><span class="spacer" /><button type="button" class="btn btn-sm" data-testid="exam-back-to-simulator" @click="leave">返回工艺主页</button></div><nav class="tabs exam-tabs" aria-label="单机练习考评模块"><button type="button" :class="{ active: route === 'menu' }" data-testid="exam-tab-menu" @click="go('menu')"><UiIcon name="House" :size="15" />主菜单</button><button type="button" :class="{ active: route.startsWith('practice') }" data-testid="exam-tab-practice" @click="go('practice-menu')"><UiIcon name="BookOpen" :size="15" />练习菜单</button><button type="button" :class="{ active: route === 'exam-login' || route === 'exam-index' || route.startsWith('exam:') }" data-testid="exam-tab-exam" @click="go('exam-login')"><UiIcon name="UserRound" :size="15" />本地身份 / 考评入口</button><button type="button" :class="{ active: route === 'history' }" data-testid="exam-tab-history" @click="go('history')"><UiIcon name="History" :size="15" />历史成绩</button></nav></template>
    <ActiveAssessmentBanner v-if="!panelIsActive" />
    <section v-if="route === 'menu'" class="ws-panel native-menu" data-testid="exam-menu">
      <div class="ws-panel-body ws-stack"><div class="menu-heading"><span class="ws-heading-icon"><UiIcon name="GraduationCap" :size="30" /></span><h2>欢迎进入甲醇加注模拟平台考评系统</h2><p class="ws-subtext">选择练习或考评，开始理论学习与操作训练。</p></div><div class="menu-cards"><button type="button" class="menu-card" data-testid="exam-menu-practice" @click="go('practice-menu')"><UiIcon name="BookOpenCheck" :size="36" /><strong>练习</strong><span>T11 / T12 理论题、操作练习、错题与收藏</span></button><button type="button" class="menu-card" data-testid="exam-menu-exam" @click="go('exam-login')"><UiIcon name="ClipboardCheck" :size="36" /><strong>考评</strong><span>录入学号姓名，选择本地限时理论 / 操作考评</span></button><button type="button" class="menu-card exit-card" data-testid="exam-menu-exit" @click="leave"><UiIcon name="LogOut" :size="36" /><strong>退出考评系统</strong><span>返回工艺主页</span></button></div><div class="ws-note warning">部分操作或故障题尚未配置独立评分规则，仅可进行关联流程练习。本地成绩不作为正式认证考评成绩。</div></div>
    </section>
    <section v-else-if="route === 'practice-menu'" class="ws-panel" data-testid="native-practice-menu"><header class="ws-panel-header"><h2>练习模式菜单</h2><button type="button" class="btn btn-sm" @click="go('menu')">返回主菜单</button></header><div class="ws-panel-body ws-stack"><div class="ws-note">使用当前本地身份 {{ student?.name }} 记录练习。理论题默认按原题库顺序，可调整题数 / 随机；收藏和历史成绩不写回 WPF 题库文件。</div><div class="ws-quick-grid"><button type="button" class="ws-quick" data-testid="native-practice-t11" @click="chooseTheory('T11', 'practice')"><span class="ws-quick-icon"><UiIcon name="BookOpen" :size="24" /></span><span><strong>T11题</strong><small>基础题库 · {{ workspace.data.questions.filter(question => question.tags.includes('T11')).length }} 题</small></span></button><button type="button" class="ws-quick" data-testid="native-practice-t12" @click="chooseTheory('T12', 'practice')"><span class="ws-quick-icon"><UiIcon name="BookOpen" :size="24" /></span><span><strong>T12题</strong><small>高级题库 · {{ workspace.data.questions.filter(question => question.tags.includes('T12')).length }} 题</small></span></button><button type="button" class="ws-quick" data-testid="native-practice-operations" @click="go('practice-index')"><span class="ws-quick-icon"><UiIcon name="Workflow" :size="24" /></span><span><strong>操作练习</strong><small>保留原 {{ nativePracticeItems.length }} 个操作 / 故障练习条目</small></span></button><button type="button" class="ws-quick" data-testid="native-practice-wrong" @click="chooseTheory('wrong', 'practice')"><span class="ws-quick-icon"><UiIcon name="CircleX" :size="24" /></span><span><strong>错题复习</strong><small>仅可见成绩中的错误与未答题</small></span></button><button type="button" class="ws-quick" data-testid="native-practice-favourites" @click="chooseTheory('favourites', 'practice')"><span class="ws-quick-icon"><UiIcon name="Star" :size="24" /></span><span><strong>收藏夹</strong><small>当前身份的可复习收藏</small></span></button><button type="button" class="ws-quick" @click="go('history')"><span class="ws-quick-icon"><UiIcon name="History" :size="24" /></span><span><strong>保存结果 / 历史记录</strong><small>实际交卷后查看、导出或删除本地成绩</small></span></button></div></div></section>
    <section v-else-if="route === 'exam-login'" class="ws-panel identity-panel" data-testid="exam-identity-form"><header class="ws-panel-header"><h2>考评身份录入（本地）</h2></header><form class="ws-panel-body ws-stack" @submit.prevent="login"><div class="ws-note">原 WPF 录入学号和姓名。本页面不需要密码，不向服务器验证身份；填写的信息仅用于本地试卷 / 操作成绩署名。刷新后活动会话仍使用开始时的身份快照。</div><label class="field-group"><span>输入学号</span><input v-model="identityNo" class="field" name="studentNo" autocomplete="off" maxlength="64" required aria-label="考评学号" data-testid="exam-student-no" /></label><label class="field-group"><span>输入姓名</span><input v-model="identityName" class="field" name="studentName" autocomplete="name" maxlength="64" required aria-label="考评姓名" data-testid="exam-student-name" /></label><div v-if="busy" class="ws-note warning" role="status">已有活动练习、考评或录制，不能在进行期间更换署名身份或开始第二个会话。可继续活动会话，计时不会暂停。</div><p v-if="identityError" class="ws-form-error" role="alert">{{ identityError }}</p><div class="ws-inline identity-actions"><button type="button" class="btn" @click="go('menu')">返回</button><button type="submit" class="btn btn-primary" :disabled="busy || !identityNo.trim() || !identityName.trim()" data-testid="exam-identity-submit"><UiIcon name="UserRoundCheck" :size="16" />保存本地身份 / 进入考评列表</button></div></form></section>
    <section v-else-if="route === 'exam-index' || route === 'practice-index'" class="ws-panel" :data-testid="route === 'exam-index' ? 'native-exam-index' : 'native-practice-index'">
      <header class="ws-panel-header"><h2>{{ route === 'exam-index' ? '考评列表' : '操作练习列表' }}</h2><span class="badge">原 WPF {{ route === 'exam-index' ? nativeExamItems.length : nativePracticeItems.length }} 个条目</span></header>
      <div class="ws-panel-body ws-stack"><div class="ws-note">{{ route === 'exam-index' ? '学号 / 姓名已录入：' + student?.studentNo + ' / ' + student?.name + '。理论考评默认从对应题库随机抽 100 题，开始前可调整。' : '请选择操作练习项目。' }}未配置独立评分规则的项目仅支持关联流程练习。</div><div class="toolbar"><div class="search-input"><UiIcon name="Search" :size="16" /><input v-model="query" class="field" placeholder="搜索编号 / 名称 / 题型" aria-label="搜索原 WPF 考评练习条目" data-testid="native-item-search" /></div><select v-model="category" class="field category-filter" aria-label="原 WPF 条目题型"><option value="">全部题型</option><option v-for="item in categories" :key="item">{{ item }}</option></select><span class="spacer" /><button type="button" class="btn" @click="go(route === 'exam-index' ? 'exam-login' : 'practice-menu')">{{ route === 'exam-index' ? '返回身份录入' : '返回练习菜单' }}</button></div>
        <div class="ws-table-wrap"><table class="data-table" :aria-label="route === 'exam-index' ? '原 WPF 考评条目' : '原 WPF 操作练习条目'"><thead><tr><th>编号</th><th>题型</th><th>{{ route === 'exam-index' ? '考评范畴' : '考核内容' }}</th><th>时间（分钟）</th><th>规则 / 对应工艺</th><th>操作</th></tr></thead><tbody><tr v-for="item in route === 'exam-index' ? examRows : practiceRows" :key="item.id" :data-testid="`${route === 'exam-index' ? 'native-exam' : 'native-practice'}-${item.id}`"><td>{{ item.id }}</td><td class="ws-nowrap">{{ item.type }}</td><td class="native-item-name">{{ item.name }}</td><td>{{ item.minutes }}<small v-if="!item.flowId" class="ws-subtext native-note">原 WPF 0 分钟，Web 可调整</small></td><td class="native-rule"><template v-if="!item.flowId"><span class="badge">原 WPF 理论题库</span></template><template v-else><span class="badge" :class="unconfigured(item) ? 'badge-warning' : operationAvailable(item) ? 'badge-success' : 'badge-muted'">{{ unconfigured(item) ? '待教师配置 / 仅关联练习' : operationAvailable(item) ? '本地训练规则' : '关联工艺不可用' }}</span><small class="ws-subtext native-note">{{ workflows.find(flow => flow.id === item.flowId)?.name || item.flowId }} · {{ nativeRuleScope(item) }}</small><small v-if="unconfigured(item)" class="ws-subtext native-note">未提供独立完整评分定义，不作为完整考评</small></template></td><td><div class="ws-inline"><button type="button" class="btn btn-sm btn-primary" :disabled="busy || !!item.flowId && (!operationAvailable(item) || route === 'exam-index' && unconfigured(item))" :data-testid="`${route === 'exam-index' ? 'native-exam-select' : 'native-practice-select'}-${item.id}`" @click="selectItem(item, route === 'exam-index' ? 'exam' : 'practice', route === 'exam-index' ? 'exam' : 'practice')">{{ route === 'exam-index' && unconfigured(item) ? '待配置，不可考评' : unconfigured(item) ? '关联流程练习' : '选择' }}</button><button v-if="item.flowId && unconfigured(item)" type="button" class="btn btn-sm" :data-testid="`native-item-info-${route}-${item.id}`" @click="selectItem(item, route === 'exam-index' ? 'exam' : 'practice', route === 'exam-index' ? 'exam' : 'practice')">查看说明</button></div></td></tr><tr v-if="!(route === 'exam-index' ? examRows : practiceRows).length"><td colspan="6" class="empty-state">没有匹配条目。</td></tr></tbody></table></div><div v-if="busy" class="ws-note warning" role="status">当前已有会话或录制，不能同时开始新题。上方活动会话可继续，切换列表不暂停真实计时。</div><p class="ws-source">来源：Simulator.Library/ExamJson/{{ route === 'exam-index' ? 'Evaluate.json' : 'Practice.json' }}。保留原名称，包括原条目中的名称重复或文字问题；缺失独立规则不以伪造成绩补齐。</p>
      </div>
    </section>
    <section v-else-if="attention" class="ws-panel" data-testid="native-operation-attention">
      <header class="ws-panel-header"><h2>模式选择 / 注意事项</h2><span class="badge">{{ attention.mode === 'exam' ? '本地限时操作考评' : unconfigured(attention.item) ? '仅关联流程练习' : '单机操作练习' }}</span></header>
      <div class="ws-panel-body ws-stack">
        <div class="ws-title-line"><h3>{{ attention.item.id }}. {{ attention.item.name }}</h3><span class="badge badge-muted">{{ attention.item.type }}</span></div>
        <div v-if="attention.item.note" class="ws-note warning" role="status">{{ attention.item.note }}</div>
        <div v-if="attention.mode === 'exam' && unconfigured(attention.item)" class="ws-note danger" role="status" data-testid="native-unconfigured-exam">此条目缺少独立完整评分定义，处于“待教师配置”状态，不能开始考评。关联流程不能替代风机启动、副泵故障、发动机故障等独立考试规则。</div>
        <div v-else-if="unconfigured(attention.item)" class="ws-note warning">只练习关联的“{{ attentionFlow?.name }}”流程，不代表已复现此原生条目的独立故障或操作评分。成绩名称会注明“关联流程练习 / 未配置独立评分定义”。</div>
        <div class="ws-details"><div class="ws-detail-item"><span>署名身份</span><strong>{{ student?.name }} · {{ student?.studentNo }}</strong></div><div class="ws-detail-item"><span>关联工艺</span><strong>{{ attentionFlow?.name || '不可用' }}</strong></div><div class="ws-detail-item"><span>本地规则范围</span><strong>{{ nativeRuleScope(attention.item) }}{{ unconfigured(attention.item) ? '（仅关联，不等于独立完整题目）' : '' }}</strong></div><div class="ws-detail-item"><span>安全检查</span><strong>{{ attentionFlow?.requiresSafety ? '需要加注作业前安全检查，通过后才开始计时' : '此流程无额外加注安全门禁' }}</strong></div></div>
        <label class="field-group minutes-field"><span>{{ attention.mode === 'exam' ? '真实考评时限' : '原条目时间（练习累计用时）' }}（分钟）</span><input v-model.number="operationMinutes" class="field" type="number" min="1" max="1440" step="1" aria-label="原生操作考评时限" data-testid="native-operation-minutes" /></label>
        <div class="ws-condition-box"><strong>注意事项</strong><ol class="attention-list"><li>仅在浏览器内训练，不构成真实船舶操作或正式认证考评；不会伪造教师服务器连接。</li><li>先完成要求的安全检查，初始工况就绪后才建立操作会话并开始计时。</li><li>在工艺画面手动操作。考评期间不能用自动演示、其他流程或加载工况覆盖本次评分。</li><li>考评按真实时钟计时，页面切换、刷新及改变仿真速度不暂停。刷新保留会话用时和记录，但工况需重新初始化，不保证完整设备快照恢复。</li><li>完成后返回工作台交卷，按本次实际操作保存成绩；缺失步骤不会补成 WPF 固定示例分数。</li></ol><label class="checkbox-label"><input v-model="agreed" type="checkbox" :disabled="attentionBlocked" data-testid="native-operation-agreement" />我已阅读并理解本地模式与上述规则</label></div>
        <div v-if="attention.mode === 'practice' && nativeAssessment && !unconfigured(attention.item)" class="ws-small-stack">
          <h3>原 Playbook 阶段与规则（练习预览）</h3><div class="ws-note">全部 Triggers 同时满足才结算阶段，Conditions 逐条评估及部分计分。下列是原定义，不用演示步骤完成度替代原阶段记录。</div>
          <div v-for="(stage, index) in nativeAssessment.stages" :key="index" class="ws-condition-box"><strong>阶段 {{ index + 1 }}. {{ stage.name }}</strong><p v-for="(rule, ruleIndex) in stage.conditions" :key="`condition-${ruleIndex}`">Conditions 条件：{{ rule.name }} · {{ rule.type }}<span v-if="rule.sourceValue != null || rule.value != null"> · 原比较值 {{ rule.sourceValue ?? rule.value }}</span></p><p v-for="(rule, ruleIndex) in stage.triggers" :key="`trigger-${ruleIndex}`">Triggers 触发器：{{ rule.name }} · {{ rule.type }}<span v-if="rule.sourceValue != null || rule.value != null"> · 原比较值 {{ rule.sourceValue ?? rule.value }}</span></p></div>
        </div>
        <div v-else-if="attention.mode === 'practice' && attentionFlow && !unconfigured(attention.item)" class="ws-small-stack"><h3>工况派生训练步骤（非原 Playbook 阶段）</h3><div v-for="(step, index) in attentionFlow.steps" :key="index" class="ws-condition-box"><strong>{{ index + 1 }}. {{ step.name }}</strong><p>{{ step.description }}</p><small>{{ step.deviceId || '传感器 / 状态判断' }} · {{ step.rules.length }} 项派生步骤条件</small></div></div>
        <div v-else-if="attention.mode === 'exam' && !unconfigured(attention.item)" class="ws-note">考评开始前及进行中不展示正确操作顺序、条件目标或答案。交卷后根据实际记录查看详细评分。</div>
        <div v-if="minutesError" class="ws-form-error" role="status">时限须为 1～1440 分钟的整数。</div><div v-if="busy" class="ws-note warning" role="status">已有活动会话或录制，不能开始第二个会话。</div>
        <div class="ws-inline attention-actions"><button type="button" class="btn" @click="go(attention.origin === 'exam' ? 'exam-index' : 'practice-index')">返回列表</button><button v-if="attention.mode === 'exam' && unconfigured(attention.item)" type="button" class="btn" :disabled="busy" data-testid="native-associated-practice" @click="go(`attention:practice:${attention.origin}:${attention.item.id}`)">仅查看 / 练习关联流程</button><span class="spacer" /><button type="button" class="btn btn-primary" :disabled="attentionBlocked || busy || minutesError || !agreed" data-testid="native-operation-start" @click="startOperation"><UiIcon name="Play" :size="16" />{{ attention.mode === 'exam' ? '开始考评' : unconfigured(attention.item) ? '开始关联流程练习' : '确认开始练习' }}</button></div>
      </div>
    </section>
    <template v-else-if="theorySelection"><p v-if="theoryItemNote" class="ws-note warning">{{ theoryItemNote }}</p><TheorySetup :key="route" return-page="exam" :mode="theorySelection.mode" :bank="theorySelection.bank" :initial-source="theorySelection.source" :default-count="defaultTheoryCount" :default-order="theorySelection.mode === 'exam' ? 'random' : 'ordered'" :title="theorySelection.bank ? `${theorySelection.bank}题库 · 单机${theorySelection.mode === 'exam' ? '考评' : '练习'}` : ''" @cancel="go(theorySelection?.mode === 'exam' ? 'exam-index' : 'practice-menu')" /></template>
    <TheoryAnswerPane v-else-if="route === 'answer' && theory" return-page="exam" />
    <OperationSessionPanel v-else-if="route === 'operation' && (operation || pending)" return-page="exam" />
    <LearnerScoreHistory v-else-if="route === 'history'" return-page="exam" />
    <section v-else-if="route === 'result' && lastScore" class="ws-panel" data-testid="native-result"><header class="ws-panel-header"><h2>{{ lastScore.mode === 'exam' ? '考评结果' : '练习结果' }} · {{ lastScore.kind === 'theory' ? '理论题' : '操作题' }}</h2><span class="badge" :class="visibleResult ? lastScore.passed ? 'badge-success' : 'badge-danger' : 'badge-muted'">{{ visibleResult ? lastScore.passed ? '通过' : '未通过' : '已提交，成绩暂不可见' }}</span></header><div class="ws-panel-body ws-stack"><div class="ws-title-line"><h3>{{ lastScore.title }}</h3><span class="ws-subtext">{{ lastScore.studentName }} · {{ lastScore.studentNo }}</span></div><p class="ws-note" role="status">{{ lastScore.reason === 'timeout' ? '真实考评时间已到，系统已自动交卷。' : '本次已手动交卷。' }}提交于 {{ formatDate(lastScore.submittedAt) }}，实际用时 {{ formatDuration(lastScore.durationSeconds) }}。结果实际保存在本浏览器，不是服务器认证成绩。</p>
      <template v-if="visibleResult"><div class="ws-metrics"><div class="ws-metric"><div class="ws-metric-label">最终得分 / 总分</div><div class="ws-metric-value" data-testid="native-result-score">{{ lastScore.score }}<small>/ {{ lastScore.maxScore }}</small></div></div><div class="ws-metric"><div class="ws-metric-label">{{ lastScore.kind === 'theory' ? '总题数 / 答对题数' : '得分点 / 通过数量' }}</div><div class="ws-metric-value">{{ lastScore.kind === 'theory' ? resultQuestions.length : lastScore.details.filter(detail => detail.kind !== 'penalty').length }}<small>/ {{ lastScore.kind === 'theory' ? correctCount : lastScore.details.filter(detail => detail.kind !== 'penalty' && detail.passed).length }} 通过</small></div></div><div class="ws-metric"><div class="ws-metric-label">{{ lastScore.kind === 'theory' ? '错误 / 未答题' : '实际通过率' }}</div><div class="ws-metric-value">{{ lastScore.kind === 'theory' ? resultQuestions.length - correctCount - unansweredCount : lastScore.accuracy }}<small>{{ lastScore.kind === 'theory' ? `/ ${unansweredCount} 未答` : '%' }}</small></div></div><div class="ws-metric"><div class="ws-metric-label">真实用时</div><div class="ws-metric-value result-duration">{{ formatDuration(lastScore.durationSeconds) }}</div></div></div><p class="ws-note warning">{{ lastScore.notes }}</p><div class="ws-title-line"><h3>{{ lastScore.kind === 'theory' ? '错误列表 / 答题情况' : '详细评分 / 实际操作' }}</h3><div class="ws-inline"><button type="button" class="ws-chip" :class="{ active: resultFilter === 'wrong' }" @click="resultFilter = 'wrong'">{{ lastScore.kind === 'theory' ? '错误 / 未答' : '未通过' }}</button><button type="button" class="ws-chip" :class="{ active: resultFilter === 'all' }" @click="resultFilter = 'all'">全部</button><button type="button" class="ws-chip" :class="{ active: resultFilter === 'passed' }" @click="resultFilter = 'passed'">通过</button></div></div><div v-if="lastScore.kind === 'theory'" class="ws-small-stack result-question-list" data-testid="native-result-wrong-list"><article v-for="detail in resultDetails" :key="detail.id" class="ws-condition-box"><strong>{{ detail.title }}</strong><p>你的答案：<span :class="detail.passed ? 'ws-success' : 'ws-danger'">{{ detail.response }}</span> · 正确答案：<span class="ws-success">{{ detail.expected }}</span></p><details><summary>查看解析与题目选项</summary><p v-for="(option, index) in detail.question?.options" :key="option.id">{{ String.fromCharCode(65 + index) }}. {{ option.text }}{{ option.correct ? ' ✓' : '' }}</p><p>{{ detail.explanation || '本题暂无解析，请以经审核的教材为准。' }}</p></details></article></div><div v-else class="ws-table-wrap"><table class="data-table" aria-label="单机操作实际评分"><thead><tr><th>步骤 / 得分点</th><th>分值</th><th>实际操作</th><th>实际得分</th><th>说明</th></tr></thead><tbody><tr v-for="detail in resultDetails" :key="detail.id"><td>{{ detail.title }}</td><td>{{ detail.maxScore }}</td><td>{{ detail.response }}</td><td :class="detail.score < 0 ? 'ws-danger' : detail.passed ? 'ws-success' : ''">{{ detail.score }}</td><td>{{ detail.message }}</td></tr></tbody></table></div><p v-if="!resultDetails.length" class="ws-subtext">当前筛选下没有{{ lastScore.kind === 'theory' ? '题目' : '评分项' }}。</p></template>
      <div v-else class="empty-state" data-testid="native-result-hidden"><UiIcon name="LockKeyhole" :size="46" class="ws-empty-icon" /><h3>已提交本地考核</h3><p>教师设置成绩暂不可见，不显示分数、正确率、通过结果、错题、答案或评分详情，也不提供成绩导出。</p></div>
      <div class="ws-inline result-actions"><button v-if="visibleResult" type="button" class="btn" data-testid="native-result-detail" @click="showDetail = true">查看完整成绩详情</button><button v-if="visibleResult" type="button" class="btn" data-testid="native-result-export" @click="exportResult(lastScore)"><UiIcon name="Download" :size="15" />保存成绩 CSV</button><button v-if="visibleResult && wrongQuestions.length" type="button" class="btn btn-primary" :disabled="busy" data-testid="native-result-retry" @click="retryWrong">重练错题 {{ wrongQuestions.length }} 题</button><span class="spacer" /><button type="button" class="btn" @click="go('history')">历史成绩</button><button type="button" class="btn" data-testid="native-result-back" @click="go(lastScore.mode === 'exam' ? 'exam-index' : 'practice-menu')">{{ lastScore.mode === 'exam' ? '返回考评列表' : '返回练习菜单' }}</button><button type="button" class="btn" @click="go('menu')">返回主菜单</button></div>
    </div></section>
    <section v-else class="ws-panel"><div class="ws-panel-body empty-state" data-testid="native-no-session"><UiIcon name="ClipboardCheck" :size="46" class="ws-empty-icon" /><h3>{{ route === 'result' ? '当前本地身份没有最近提交结果' : '当前没有属于此身份 / 模块的活动会话' }}</h3><p>已提交成绩在历史记录中查看；活动会话保留在原工作台，不能同时创建第二套答题状态。</p><div class="ws-inline empty-actions"><button type="button" class="btn" @click="go('history')">查看历史成绩</button><button type="button" class="btn btn-primary" @click="go('menu')">返回主菜单</button></div></div></section>
    <ScoreDetailModal v-if="showDetail && lastScore" :record="lastScore" return-page="exam" @close="showDetail = false" />
    <BaseModal v-if="leaving" title="离开单机练习 / 考评系统" :width="550" :close-on-backdrop="false" @close="leaving = false"><div class="ws-modal-content ws-stack" data-testid="native-exit-confirmation"><div class="ws-note warning">当前有未结束的本地会话。仅离开页面会保留答案 / 操作记录，真实考评计时仍继续；如果选择结束本次，未提交内容不会生成成绩。</div><p>需要保存本次成绩，请返回作答或操作会话交卷。历史成绩不受页面离开影响。</p></div><template #footer><button type="button" class="btn" @click="leaving = false">留在工作台</button><button type="button" class="btn" data-testid="native-exit-keep" @click="leaveKeepingSession">保留会话，返回工艺</button><button type="button" class="btn btn-danger" data-testid="native-exit-end" @click="endAndLeave">结束本次再返回</button></template></BaseModal>
  </WorkspaceFrame>
</template>

