@media(max-width:900px){.menu-cards{grid-template-columns:1fr}.menu-card{flex-direction:row;padding:18px;text-align:left;gap:16px}.menu-card span{text-align:left;flex:1}.menu-card strong{font-size:18px;min-width:85px}.native-menu .ws-panel-body{padding:20px}}@media(max-width:550px){.menu-heading h2{font-size:20px}.menu-card{flex-wrap:wrap}.category-filter{width:100%}.exam-tabs button{flex:1;white-space:nowrap}.menu-card span{flex-basis:100%}.result-duration{font-size:19px}}
